import fs from "node:fs/promises";
import { describe, expect, it } from "vitest";
import { parse } from "yaml";
import { BUILTIN_ADAPTERS, ManifestSchema } from "../src/config/schema.js";
import { OPENCLAW_SUPPORT_CATALOG } from "../src/providers/catalog.js";

type WebhookDefaults = { path: string; port: number };

function schemaWebhookDefaults(adapter: (typeof BUILTIN_ADAPTERS)[number]): WebhookDefaults {
  const manifest = ManifestSchema.parse({
    fixtures: [],
    providers: { provider: { adapter, [adapter]: {} } },
  });
  const provider = manifest.providers.provider as unknown as Record<string, unknown>;
  const adapterConfig = provider[adapter] as { webhook?: WebhookDefaults } | undefined;
  if (!adapterConfig?.webhook) {
    throw new Error(`Adapter ${adapter} does not define webhook defaults.`);
  }
  return { path: adapterConfig.webhook.path, port: adapterConfig.webhook.port };
}

describe("channel setup contracts", () => {
  it("ships a schema-valid example covering every built-in adapter", async () => {
    const manifest = ManifestSchema.parse(
      parse(await fs.readFile("fixtures/examples/crabline.example.yaml", "utf8")),
    );
    const exampleAdapters = Object.values(manifest.providers)
      .map((provider) => provider.adapter)
      .toSorted();
    const builtinAdapters = BUILTIN_ADAPTERS.filter((adapter) => adapter !== "script").toSorted();

    expect(exampleAdapters).toEqual(builtinAdapters);

    const targetId = manifest.fixtures.find((fixture) => fixture.provider === "mattermost")?.target
      .id;
    expect(targetId).toMatch(/^[a-z0-9]{26}$/u);
    expect(manifest.fixtures.find((fixture) => fixture.provider === "imessage")?.target.id).toBe(
      "iMessage;-;chat-guid",
    );
  });

  it("keeps documented support lists synchronized with schema and catalog", async () => {
    const [readme, channelSetup, exampleText] = await Promise.all([
      fs.readFile("README.md", "utf8"),
      fs.readFile("docs/channel-setup.md", "utf8"),
      fs.readFile("fixtures/examples/crabline.example.yaml", "utf8"),
    ]);
    const readmeBuiltinSection = readme.slice(
      readme.indexOf("The built-in providers are:"),
      readme.indexOf("The `script` adapter"),
    );
    const documentedBuiltinAdapters = Array.from(
      readmeBuiltinSection.matchAll(/^- `([^`]+)`$/gmu),
      (match) => match[1],
    ).toSorted();
    const documentedCatalog = Array.from(
      channelSetup.matchAll(/^\| `([^`]+)`\s+\| `(ready|bridge)`\s+\|$/gmu),
      (match) => ({ platform: match[1]!, status: match[2]! }),
    ).toSorted((left, right) => left.platform.localeCompare(right.platform));
    const expectedCatalog = OPENCLAW_SUPPORT_CATALOG.map(({ platform, status }) => ({
      platform,
      status,
    })).toSorted((left, right) => left.platform.localeCompare(right.platform));
    const documentedWebhooks = new Map(
      Array.from(
        channelSetup.matchAll(/^\| `([^`]+)`\s+\| `([^`]+)`\s+\| `([0-9]+)`\s+\|$/gmu),
        (match) => [match[1]!, { path: match[2]!, port: Number(match[3]) }] as const,
      ),
    );
    const example = ManifestSchema.parse(parse(exampleText));
    const webhookAdapters = BUILTIN_ADAPTERS.filter(
      (adapter) => adapter !== "loopback" && adapter !== "script",
    );

    expect(documentedBuiltinAdapters).toEqual(
      BUILTIN_ADAPTERS.filter((adapter) => adapter !== "script").toSorted(),
    );
    expect(documentedCatalog).toEqual(expectedCatalog);
    expect([...documentedWebhooks.keys()].toSorted()).toEqual(webhookAdapters.toSorted());
    for (const adapter of webhookAdapters) {
      const defaults = schemaWebhookDefaults(adapter);
      expect(documentedWebhooks.get(adapter)).toEqual(defaults);
      const provider = example.providers[adapter] as unknown as Record<string, unknown>;
      const config = provider[adapter] as { webhook?: WebhookDefaults };
      expect(config.webhook).toMatchObject(defaults);
    }
  });

  it("documents native target and admin-ingress identifiers", async () => {
    const [readme, channelSetup] = await Promise.all([
      fs.readFile("README.md", "utf8"),
      fs.readFile("docs/channel-setup.md", "utf8"),
    ]);

    for (const document of [readme, channelSetup]) {
      expect(document).toContain("`U1234567890`");
      expect(document).toContain("`iMessage;-;chat-guid`");
      expect(document).toContain("`$eventid:matrix.org`");
      expect(document).toContain("contain 5-32 letters");
      expect(document).toContain("do not support `threadId` targets");
      expect(document).toContain("exactly 26 lowercase alphanumeric");
      expect(document).toContain("`a:opaque-conversation-id`");
    }
    expect(channelSetup).toContain("optional `senderName`, `roomName`, `direct`, and `threadId`");
    expect(channelSetup).toContain("`/crabline/zalo/inbound`");
    expect(channelSetup).toContain("`X-Crabline-Admin-Token`");
    const matrixSection = channelSetup.slice(
      channelSetup.indexOf("### Matrix"),
      channelSetup.indexOf("Slack:"),
    );
    expect(matrixSection).toContain("`endpoints.adminInboundUrl`");
    expect(matrixSection).toContain("`adminToken`");
    expect(matrixSection).toContain("`X-Crabline-Admin-Token`");
  });

  it("documents ready-file protections and Mattermost ingress authentication", async () => {
    const [readme, channelSetup] = await Promise.all([
      fs.readFile("README.md", "utf8"),
      fs.readFile("docs/channel-setup.md", "utf8"),
    ]);

    for (const document of [readme, channelSetup]) {
      expect(document).toContain("generated provider and admin credentials");
      expect(document).toContain("POSIX mode `0600`");
      expect(document).toContain("Exclude ready files from version control and CI artifact");
      expect(document).toContain("delete them after use");
    }
    expect(channelSetup).toContain("Mattermost `webhookToken` or `MATTERMOST_TOKEN`");
    expect(channelSetup).toContain("Externally reachable callbacks require this token");
    expect(channelSetup).toContain("an HTTPS\n  `webhook.publicUrl`");
  });
});

import { describe, expect, it } from "vitest";
import { CrablineError } from "../src/core/errors.js";
import { requireExternalWebhookAuthentication } from "../src/providers/builtin/external-webhook-auth.js";

const base = {
  provider: "Example",
  requirement: "example.signingSecret",
};

describe("external webhook authentication policy", () => {
  it("requires authentication before exposing webhook ingress", () => {
    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: false,
        webhook: { host: "0.0.0.0" },
      }),
    ).toThrow(/externally reachable webhooks require example\.signingSecret/u);
  });

  it("requires an HTTPS public URL for authenticated external ingress", () => {
    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        webhook: { host: "0.0.0.0" },
      }),
    ).toThrow(/public callback URL with HTTPS/u);

    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        authenticatedIngressUrls: ["http://hooks.example.test/events"],
        webhook: { host: "0.0.0.0" },
      }),
    ).toThrow(/require HTTPS/u);

    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        authenticatedIngressUrls: ["https://hooks.example.test/events"],
        webhook: {
          host: "127.0.0.1",
          publicUrl: "http://hooks.example.test/secondary",
        },
      }),
    ).toThrow(/require HTTPS/u);

    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        webhook: {
          host: "127.0.0.1",
          publicUrl: "http://hooks.example.test/events",
        },
      }),
    ).toThrow(/require HTTPS/u);
  });

  it.each([true, false])(
    "classifies malformed public callback URLs as configuration errors when authenticated=%s",
    (authenticated) => {
      let failure: unknown;
      try {
        requireExternalWebhookAuthentication({
          ...base,
          authenticated,
          webhook: { host: "127.0.0.1", publicUrl: "not a URL" },
        });
      } catch (error) {
        failure = error;
      }

      expect(failure).toBeInstanceOf(CrablineError);
      expect(failure).toMatchObject({
        kind: "config",
        message: "Example public callback URL is invalid.",
      });
    },
  );

  it("allows HTTPS frontends and loopback-local HTTP", () => {
    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        webhook: {
          host: "0.0.0.0",
          publicUrl: "https://hooks.example.test/events",
        },
      }),
    ).not.toThrow();

    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        authenticatedIngressUrls: ["https://hooks.example.test/events"],
        webhook: { host: "0.0.0.0" },
      }),
    ).not.toThrow();

    for (const publicUrl of [
      "http://127.0.0.1:8787/events",
      "http://localhost:8787/events",
      "http://[::1]:8787/events",
    ]) {
      expect(() =>
        requireExternalWebhookAuthentication({
          ...base,
          authenticated: true,
          webhook: { host: "127.0.0.1", publicUrl },
        }),
      ).not.toThrow();
    }

    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: true,
        authenticatedIngressUrls: ["http://localhost:8787/primary"],
        webhook: {
          host: "127.0.0.1",
          publicUrl: "http://127.0.0.1:8787/secondary",
        },
      }),
    ).not.toThrow();
  });

  it.each(["ftp://127.0.0.1/events", "file:///events", "ws://localhost/events"])(
    "rejects non-HTTP callback protocol %s even on loopback",
    (publicUrl) => {
      expect(() =>
        requireExternalWebhookAuthentication({
          ...base,
          authenticated: false,
          webhook: { host: "127.0.0.1", publicUrl },
        }),
      ).toThrow(/require HTTPS/u);
    },
  );

  it.each([
    ["127.0.0.1", "http://127.0.0.1:8787/events"],
    ["localhost", "http://localhost:8787/events"],
    ["::1", "http://[::1]:8787/events"],
  ])("allows unauthenticated loopback ingress on %s", (host, publicUrl) => {
    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: false,
        webhook: { host, publicUrl },
      }),
    ).not.toThrow();
  });

  it.each([
    ["external callback", "127.0.0.1", "https://hooks.example.test/events"],
    ["external bind", "0.0.0.0", "http://127.0.0.1:8787/events"],
  ])("requires authentication for %s", (_label, host, publicUrl) => {
    expect(() =>
      requireExternalWebhookAuthentication({
        ...base,
        authenticated: false,
        webhook: { host, publicUrl },
      }),
    ).toThrow(/externally reachable webhooks require example\.signingSecret/u);
  });
});

import { fork } from "node:child_process";
import { once } from "node:events";
import { writeFile } from "node:fs/promises";
import { Agent, request } from "node:https";
import path from "node:path";
import { expect, it } from "vitest";
import { startFeishuServer, type ServerRequestEvent } from "../src/index.js";
import { FEISHU_TEST_CERTIFICATE, FEISHU_TEST_KEY } from "./fixtures/feishu-tls.js";
import { createTempDir, disposeTempDir, requestHttp } from "./test-helpers.js";

it.for(["admission-first", "send-first"] as const)(
  "preserves native DM chat identity through official SDK routes (%s)",
  async (order, { onTestFinished, signal }) => {
    const directory = await createTempDir();
    const events: ServerRequestEvent[] = [];
    const server = await startFeishuServer({
      recorderPath: path.join(directory, "events.jsonl"),
      onEvent: (event) => {
        events.push(event);
      },
    });
    const child = fork(path.resolve("test/fixtures/feishu-sdk-client.ts"), [], {
      execArgv: ["--import", "tsx"],
      env: { PATH: process.env.PATH, HOME: directory, TMPDIR: directory },
      stdio: ["ignore", "pipe", "pipe", "ipc"],
    });
    const exit = once(child, "exit");
    let output = "";
    for (const stream of [child.stdout, child.stderr]) {
      stream?.on("data", (chunk: Buffer) => {
        output = (output + chunk.toString()).slice(-16_384);
      });
    }
    onTestFinished(async () => {
      if (child.connected) {
        child.send({ type: "stop" });
      }
      const timer = setTimeout(() => child.kill("SIGKILL"), 2_000);
      try {
        const [code, exitSignal] = await exit;
        expect({ code, exitSignal, output }).toMatchObject({ code: 0, exitSignal: null });
      } finally {
        clearTimeout(timer);
        await server.close();
        await disposeTempDir(directory);
      }
    });
    const admit = (chatId: string) =>
      requestHttp({
        method: "POST",
        url: server.manifest.endpoints.adminInboundUrl,
        headers: {
          "content-type": "application/json",
          "x-crabline-admin-token": [REDACTED],
        },
        body: JSON.stringify({
          messageId: "om_dm_inbound",
          eventId: "event-dm-inbound",
          chatId,
          senderId: "ou_dm_peer",
          text: "SDK DM input",
        }),
      });
    let chatId = "oc_existing_dm";
    let admitted: Awaited<ReturnType<typeof admit>> | undefined;
    if (order === "admission-first") {
      admitted = await admit(chatId);
    }
    expect(admitted?.status).toBe(order === "admission-first" ? 200 : undefined);
    const outcome = once(child, "message", { signal });
    child.send({ type: "start", ...server.manifest, chatIdentity: order });
    let [result] = await outcome;
    const firstSend = {
      type: "first-dm",
      first: { code: 0, data: { chat_id: expect.any(String) } },
    };
    expect({ result, output }).toMatchObject({
      result: order === "send-first" ? firstSend : { type: "chat-identity" },
    });
    if (order === "send-first") {
      chatId = result.first.data.chat_id;
      admitted = await admit(chatId);
    }
    expect(admitted?.status).toBe(200);
    if (order === "send-first") {
      const completed = once(child, "message", { signal });
      child.send({ type: "release" });
      [result] = await completed;
    }
    expect({ result, output }).toMatchObject({ result: { type: "chat-identity" } });
    for (const response of [result.direct, result.explicit, result.reply]) {
      expect(response).toMatchObject({ code: 0, data: { chat_id: chatId } });
    }
    expect(result.direct.data.parent_id).toBeUndefined();
    expect(result.explicit.data.parent_id).toBeUndefined();
    expect(result.reply.data.parent_id).toBe("om_dm_inbound");
    expect(
      events.filter((event) => (event.body as { stage?: string }).stage === "outbound.accepted"),
    ).toHaveLength(order === "send-first" ? 4 : 3);
  },
);

it.for(["secret", "app ID"])(
  "reports an invalid discovery %s as terminal through the reconnect-enabled SDK",
  async (credential, { onTestFinished, signal }) => {
    const directory = await createTempDir();
    const events: ServerRequestEvent[] = [];
    const server = await startFeishuServer({
      appId: "cli_0123456789abcdef",
      recorderPath: path.join(directory, "events.jsonl"),
      onEvent: (event) => {
        events.push(event);
      },
    });
    const child = fork(path.resolve("test/fixtures/feishu-sdk-client.ts"), [], {
      execArgv: ["--import", "tsx"],
      env: { PATH: process.env.PATH, HOME: directory, TMPDIR: directory },
      stdio: ["ignore", "pipe", "pipe", "ipc"],
    });
    const exit = once(child, "exit");
    let output = "";
    for (const stream of [child.stdout, child.stderr]) {
      stream?.on("data", (chunk: Buffer) => {
        output = (output + chunk.toString()).slice(-16_384);
      });
    }
    onTestFinished(async () => {
      if (child.connected) {
        child.send({ type: "stop" });
      }
      const timer = setTimeout(() => child.kill("SIGKILL"), 2_000);
      try {
        const [code, exitSignal] = await exit;
        expect({ code, exitSignal, output }).toMatchObject({ code: 0, exitSignal: null });
      } finally {
        clearTimeout(timer);
        await server.close();
        await disposeTempDir(directory);
      }
    });
    const outcome = once(child, "message", { signal });
    child.send({
      type: "start",
      ...server.manifest,
      appId: credential === "app ID" ? "cli_ffffffffffffffff" : server.manifest.appId,
      appSecret: credential === "secret" ? "wrong" : server.manifest.appSecret,
      rejectCredentials: true,
    });
    const [result] = await outcome;
    expect({ result, output }).toMatchObject({
      result: {
        type: "auth-error",
        message: "pullConnectConfig failed: code=514, msg=Invalid application credentials",
        status: { state: "failed", reconnectAttempts: 0 },
        discoveryRequests: 1,
      },
    });
    expect(result.status).not.toHaveProperty("nextConnectTime");
    expect(
      events.filter((event) => (event.body as { stage?: string }).stage === "websocket.discovered"),
    ).toHaveLength(0);
    expect(
      events.filter((event) => (event.body as { stage?: string }).stage === "websocket.connected"),
    ).toHaveLength(0);
    expect(
      events.filter((event) => (event.body as { stage?: string }).stage === "inbound.admitted"),
    ).toHaveLength(0);
  },
);

it("uses a custom app ID with the official SDK for TLS auth, REST, fragmented events and dispatcher-barrier ACKs", async ({
  onTestFinished,
  signal,
}) => {
  const directory = await createTempDir();
  const caPath = path.join(directory, "ca.pem");
  await writeFile(caPath, FEISHU_TEST_CERTIFICATE);
  const events: ServerRequestEvent[] = [];
  const server = await startFeishuServer({
    appId: "cli_0123456789aBcDeF",
    tls: { key: FEISHU_TEST_KEY, cert: FEISHU_TEST_CERTIFICATE },
    recorderPath: path.join(directory, "events.jsonl"),
    onEvent: (event) => {
      events.push(event);
    },
  });
  const agent = new Agent({ ca: FEISHU_TEST_CERTIFICATE });
  const child = fork(path.resolve("test/fixtures/feishu-sdk-client.ts"), [], {
    execArgv: ["--import", "tsx"],
    env: {
      PATH: process.env.PATH,
      HOME: directory,
      TMPDIR: directory,
      NODE_EXTRA_CA_CERTS: caPath,
    },
    stdio: ["ignore", "pipe", "pipe", "ipc"],
  });
  const exit = once(child, "exit");
  const messages: Array<{
    type: string;
    event?: unknown;
    message?: string;
    lookup?: unknown;
    reply?: unknown;
  }> = [];
  let output = "";
  for (const stream of [child.stdout, child.stderr]) {
    stream?.on("data", (chunk: Buffer) => {
      output = (output + chunk.toString()).slice(-16_384);
    });
  }
  child.on("message", (message) => messages.push(message as (typeof messages)[number]));
  const stop = async () => {
    if (child.connected) {
      child.send({ type: "stop" });
    }
    const timer = setTimeout(() => child.kill("SIGKILL"), 2_000);
    try {
      const [code, exitSignal] = await exit;
      expect({ code, exitSignal }).toEqual({ code: 0, exitSignal: null });
    } finally {
      clearTimeout(timer);
      agent.destroy();
      await server.close();
      await disposeTempDir(directory);
    }
  };
  onTestFinished(stop);
  const deadline = Date.now() + 20_000;
  const wait = async (predicate: () => boolean) => {
    while (!predicate()) {
      signal.throwIfAborted();
      const failure = messages.find((message) => message.type === "failure");
      if (failure || child.exitCode !== null || Date.now() >= deadline) {
        throw new Error(failure?.message ?? `SDK fixture did not progress: ${output}`);
      }
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  };
  const stage = (name: string) =>
    events.filter((event) => (event.body as { stage?: string }).stage === name);
  child.send({ type: "start", ...server.manifest });
  await wait(() => stage("websocket.connected").length === 1);
  expect(stage("outbound.accepted")).toHaveLength(6);
  expect(stage("tenant.token.issued")).toHaveLength(1);
  const inboundMessages = [
    ["custom-id", "中文跨片🦊".repeat(21)],
    ["custom.dotted.id", "SDK dotted ID"],
    ["消息🦊", "SDK_THROW"],
  ] as const;
  for (const [index, [messageId, text]] of inboundMessages.entries()) {
    const result = await requestHttp({
      requestImpl: request,
      agent,
      method: "POST",
      url: server.manifest.endpoints.adminInboundUrl,
      headers: {
        "content-type": "application/json",
        "x-crabline-admin-token": [REDACTED],
      },
      body: JSON.stringify({
        messageId,
        eventId: `event-sdk-${index}`,
        chatId: "oc_sdk",
        senderId: "ou_sdk",
        text,
        fragments: 7,
        fragmentOrder: [4, 2, 1, 5, 3, 0, 6],
      }),
    });
    expect(result.status).toBe(200);
    await wait(() => messages.filter((message) => message.type === "event").length === index + 1);
    expect(messages.filter((message) => message.type === "event")[index]).toMatchObject({
      lookup: { code: 0, data: { items: [{ message_id: messageId }] } },
      reply: { code: 0, data: { parent_id: messageId, root_id: messageId } },
    });
    expect(stage("sdk.ack")).toHaveLength(index);
    await new Promise((resolve) => setTimeout(resolve, 30));
    expect(stage("sdk.ack")).toHaveLength(index);
    child.send({ type: "release" });
    await wait(() => stage("sdk.ack").length === index + 1);
    expect(stage("sdk.ack")[index]!.body).toMatchObject({
      messageId,
      code: text === "SDK_THROW" ? 500 : 200,
    });
    expect(stage("sdk.ack")[index]!.body).toHaveProperty(
      "headers",
      expect.arrayContaining([{ key: "seq", value: "6" }]),
    );
  }
  expect(stage("sdk.ack")[0]!.body).toHaveProperty(
    "data",
    Buffer.from(JSON.stringify({ handled: true })).toString("base64"),
  );
  expect(stage("outbound.accepted")).toHaveLength(9);
  await wait(() => stage("websocket.pong").length > 0);
  expect(messages.filter((message) => message.type === "event")[0]!.event).toMatchObject({
    message: { content: JSON.stringify({ text: "中文跨片🦊".repeat(21) }) },
  });
}, 30_000);

// Run in a child: the official SDK changes protobufjs' process-global Long setting.
import * as Lark from "@larksuiteoapi/node-sdk";

let websocket: Lark.WSClient | undefined;
let release: (() => void) | undefined;

process.on(
  "message",
  (message: {
    type: string;
    appId?: string;
    appSecret?: string;
    baseUrl?: string;
    rejectCredentials?: boolean;
    chatIdentity?: "admission-first" | "send-first";
  }) => {
    if (message.type === "release") {
      release?.();
      return;
    }
    if (message.type === "stop") {
      websocket?.close({ force: true });
      process.disconnect();
      return;
    }
    if (message.type !== "start" || !message.appId || !message.appSecret || !message.baseUrl) {
      throw new Error("Invalid SDK fixture command");
    }
    const { appId, appSecret, baseUrl } = message;
    let discoveryRequests = 0;
    // Keep the SDK's route expansion and response handling; change only the origin.
    Lark.defaultHttpInstance.interceptors.request.use((request) => {
      const url = new URL(request.url!);
      if (url.origin !== "https://open.feishu.cn") {
        throw new Error("Unexpected SDK destination");
      }
      if (url.pathname === "/callback/ws/endpoint") {
        discoveryRequests++;
      }
      request.url = `${baseUrl}${url.pathname}${url.search}`;
      request.proxy = false;
      return request;
    });
    const run = async () => {
      if (message.rejectCredentials) {
        // Observe HTTP rejection without converting it into the SDK's terminal error.
        Lark.defaultHttpInstance.interceptors.response.use(undefined, (error: unknown) => {
          process.send?.({
            type: "http-error",
            message: error instanceof Error ? error.message : String(error),
          });
          return Promise.reject(error);
        });
        websocket = new Lark.WSClient({
          appId,
          appSecret,
          autoReconnect: true,
          loggerLevel: Lark.LoggerLevel.error,
          onReady: () => {
            process.send?.({ type: "unexpected-ready" });
          },
          onError: (error) => {
            process.send?.({
              type: "auth-error",
              message: error.message,
              status: websocket?.getConnectionStatus(),
              discoveryRequests,
            });
          },
        });
        await websocket.start({ eventDispatcher: new Lark.EventDispatcher({}) });
        return;
      }
      const client = new Lark.Client({ appId, appSecret, loggerLevel: Lark.LoggerLevel.error });
      if (message.chatIdentity) {
        const sendDirect = () =>
          client.im.message.create({
            params: { receive_id_type: "open_id" },
            data: {
              receive_id: "ou_dm_peer",
              msg_type: "text",
              content: JSON.stringify({ text: "SDK direct response" }),
            },
          });
        const first = await sendDirect();
        if (message.chatIdentity === "send-first") {
          const barrier = new Promise<void>((resolve) => {
            release = resolve;
          });
          process.send?.({ type: "first-dm", first });
          await barrier;
          release = undefined;
        }
        const chatId =
          message.chatIdentity === "send-first" ? first.data?.chat_id : "oc_existing_dm";
        if (!chatId) {
          throw new Error("SDK direct send did not return a chat ID");
        }
        const direct = message.chatIdentity === "send-first" ? await sendDirect() : first;
        const explicit = await client.im.message.create({
          params: { receive_id_type: "chat_id" },
          data: {
            receive_id: chatId,
            msg_type: "text",
            content: JSON.stringify({ text: "SDK chat response" }),
          },
        });
        const reply = await client.im.message.reply({
          path: { message_id: "om_dm_inbound" },
          data: { msg_type: "text", content: JSON.stringify({ text: "SDK reply" }) },
        });
        process.send?.({ type: "chat-identity", direct, explicit, reply });
        return;
      }
      for (const [msg_type, content] of [
        ["text", { text: "SDK 文本" }],
        ["post", { zh_cn: { title: "", content: [[{ tag: "text", text: "SDK 富文本" }]] } }],
        ["interactive", { elements: [{ tag: "markdown", content: "SDK 卡片" }] }],
      ] as const) {
        const response = await client.im.message.create({
          params: { receive_id_type: "chat_id" },
          data: { receive_id: "oc_sdk", msg_type, content: JSON.stringify(content) },
        });
        if (response.code !== 0 || !response.data?.message_id) {
          throw new Error("SDK create was not accepted");
        }
        const reply = await client.im.message.reply({
          path: { message_id: response.data.message_id },
          data: { msg_type: "text", content: JSON.stringify({ text: "SDK 回复" }) },
        });
        if (reply.code !== 0) {
          throw new Error("SDK reply was not accepted");
        }
      }
      const dispatcher = new Lark.EventDispatcher({}).register({
        "im.message.receive_v1": async (event) => {
          const lookup = await client.im.message.get({
            path: { message_id: event.message.message_id },
          });
          const reply = await client.im.message.reply({
            path: { message_id: event.message.message_id },
            data: { msg_type: "text", content: JSON.stringify({ text: "SDK 自定义 ID 回复" }) },
          });
          const barrier = new Promise<void>((resolve) => {
            release = resolve;
          });
          process.send?.({ type: "event", event, lookup, reply });
          await barrier;
          release = undefined;
          if (event.message.content.includes("SDK_THROW")) {
            throw new Error("Expected dispatcher failure");
          }
          return { handled: true };
        },
      });
      websocket = new Lark.WSClient({
        appId,
        appSecret,
        autoReconnect: false,
        loggerLevel: Lark.LoggerLevel.error,
      });
      await websocket.start({ eventDispatcher: dispatcher });
      process.send?.({ type: "started" });
    };
    void run().catch((error: unknown) => {
      process.send?.({
        type: "failure",
        message: error instanceof Error ? error.message : String(error),
      });
      websocket?.close({ force: true });
      process.exitCode = 1;
      process.disconnect();
    });
  },
);

import type { Dirent } from "node:fs";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { parse } from "yaml";

type WorkflowStep = {
  run?: string;
  uses?: string;
  with?: Record<string, unknown>;
};

type Workflow = {
  jobs?: Record<
    string,
    {
      container?: string | { image?: string };
      services?: Record<string, string | { image?: string }>;
      steps?: WorkflowStep[];
      uses?: string;
    }
  >;
  on?: {
    pull_request?: { paths?: string[] };
    push?: { paths?: string[] };
  };
};

type CompositeAction = {
  runs?: {
    image?: string;
    steps?: WorkflowStep[];
    using?: string;
  };
};

async function readWorkflow(filePath: string): Promise<Workflow> {
  return parse(await fs.readFile(filePath, "utf8")) as Workflow;
}

