      fs
        .readFile(".github/codeql/codeql-actions-security.yml", "utf8")
        .then((contents) => parse(contents) as { paths?: string[] }),
      fs
        .readFile(".github/codeql/codeql-typescript-security.yml", "utf8")
        .then((contents) => parse(contents) as { paths?: string[] }),
