    expect(codeowners).toContain("/.github/actions/ @openclaw/openclaw-secops");
    expect(codeowners).toContain("/.github/pull_request_template.md @openclaw/openclaw-secops");
    expect(codeowners).toContain("/AGENTS.md @openclaw/openclaw-secops");
    expect(codeowners).toContain("/tools/ @openclaw/openclaw-secops");
    expect(codeqlWorkflow.on?.push?.paths).toContain(".github/actions/**");
    expect(codeqlWorkflow.on?.pull_request?.paths).toContain(".github/actions/**");
    expect(codeqlWorkflow.on?.push?.paths).toContain("tools/**");
    expect(codeqlWorkflow.on?.pull_request?.paths).toContain("tools/**");
    expect(actionsConfig.paths).toContain(".github/actions");
    expect(typescriptConfig.paths).toContain("tools");
  });

  it("exempts security pull requests from stale automation", async () => {
    const workflow = await readWorkflow(".github/workflows/stale.yml");
    const staleStep = Object.values(workflow.jobs ?? {})
      .flatMap((job) => job.steps ?? [])
      .find((step) => step.uses?.startsWith("actions/stale@"));

    expect(String(staleStep?.with?.["exempt-pr-labels"]).split(",")).toContain("security");
  });
});

async function collectExternalActionRefs(root: string): Promise<string[]> {
  const workflowDirectory = path.join(root, ".github", "workflows");
  const workflowFiles = await listYamlFiles(workflowDirectory);
  const workflowRefs = (
    await Promise.all(
      workflowFiles.map(async (filePath) => {
        const workflow = await readWorkflow(filePath);
        return Object.values(workflow.jobs ?? {}).map((job) => {
          const containerImage = workflowImage(job.container);
          const serviceImages = Object.values(job.services ?? {}).flatMap((service) => {
            const image = workflowImage(service);
            return image ? [image] : [];
          });
          const stepRefs = job.steps?.flatMap((step) => (step.uses ? [step.uses] : [])) ?? [];
          return {
            external: [
              ...(job.uses && !job.uses.startsWith("./") ? [job.uses] : []),
              ...(containerImage ? [containerImage] : []),
              ...serviceImages,
              ...stepRefs.filter((uses) => !uses.startsWith("./")),
            ],
            localActions: stepRefs.filter((uses) => uses.startsWith("./")),
          };
        });
      }),
    )
  ).flat();

  const externalRefs = workflowRefs.flatMap((refs) => refs.external);
  const actionFiles = await listYamlFiles(path.join(root, ".github", "actions"));
  for (const localRef of workflowRefs.flatMap((refs) => refs.localActions)) {
    actionFiles.push(await resolveLocalActionManifest(root, localRef));
  }

  const pending = [...new Set(actionFiles)];
  const visited = new Set<string>();
  while (pending.length > 0) {
    const filePath = pending.shift()!;
    if (visited.has(filePath)) {
      continue;
    }
    visited.add(filePath);
    const action = parse(await fs.readFile(filePath, "utf8")) as CompositeAction;
    const refs =
      action.runs?.using === "composite"
        ? (action.runs.steps?.flatMap((step) => (step.uses ? [step.uses] : [])) ?? [])
        : action.runs?.using === "docker" && action.runs.image?.startsWith("docker://")
          ? [action.runs.image]
          : [];
    for (const uses of refs) {
      if (uses.startsWith("./")) {
        pending.push(await resolveLocalActionManifest(root, uses));
      } else {
        externalRefs.push(uses);
      }
    }
  }

  return externalRefs;
}

async function resolveLocalActionManifest(root: string, uses: string): Promise<string> {
  const resolved = path.resolve(root, uses.slice(2));
  const relative = path.relative(root, resolved);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`Local action escapes the repository: ${uses}`);
  }
  for (const fileName of ["action.yml", "action.yaml"]) {
    const manifestPath = path.join(resolved, fileName);
    try {
      if ((await fs.stat(manifestPath)).isFile()) {
        return manifestPath;
      }
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
        throw error;
      }
    }
  }
  throw new Error(`Local action manifest is missing: ${uses}`);
}

function workflowImage(value: string | { image?: string } | undefined): string | undefined {
  const image = typeof value === "string" ? value : value?.image;
  return image ? `docker://${image}` : undefined;
}

function isImmutableActionRef(actionRef: string): boolean {
  if (actionRef.startsWith("docker://")) {
    return /^docker:\/\/[^@\s]+@sha256:[0-9a-f]{64}$/u.test(actionRef);
  }
  return /^[^@\s]+@[0-9a-f]{40}$/u.test(actionRef);
}

async function listYamlFiles(directory: string): Promise<string[]> {
  let entries: Dirent<string>[];
  try {
    entries = await fs.readdir(directory, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return [];
    }
    throw error;
  }

  return (
    await Promise.all(
      entries.map(async (entry) => {
        const entryPath = path.join(directory, entry.name);
        if (entry.isDirectory()) {
          return await listYamlFiles(entryPath);
        }
        return /\.ya?ml$/u.test(entry.name) ? [entryPath] : [];
      }),
    )
  ).flat();
}

import { describe, expect, it, vi } from "vitest";
import { runFixtureCommand } from "../src/core/run.js";
import type { ManifestDefinition } from "../src/config/schema.js";
import { OPENCLAW_SUPPORT_CATALOG } from "../src/providers/catalog.js";
import type { Registry } from "../src/providers/registry.js";
import type { ProviderAdapter } from "../src/providers/types.js";

const manifest: ManifestDefinition = {
  configVersion: 1,
  fixtures: [
    {
      env: [],
      id: "fixture",
      inboundMatch: { author: "assistant", nonce: "contains", strategy: "contains" },
      mode: "roundtrip",
      provider: "mock",
      retries: 1,
      tags: [],
      target: { id: "echo", metadata: {} },
      timeoutMs: 10,
    },
  ],
  providers: {
    mock: {
      adapter: "loopback",
      capabilities: ["probe", "send", "roundtrip", "agent"],
      env: [],
      platform: "loopback",
      status: "active",
    },
  },
  userName: "crabline",
};

describe("runFixtureCommand retries", () => {
  it.each([
    ["backward", -60_000],
    ["forward", 60_000],
  ] as const)(
    "keeps inbound deadlines monotonic when the wall clock moves %s",
    async (_direction, wallShift) => {
      let wallNow = 10_000;
      let waitCalls = 0;
      const dateNowSpy = vi.spyOn(Date, "now").mockImplementation(() => wallNow);
      const provider: ProviderAdapter = {
        id: "mock",
        platform: "loopback",
        status: "ready",
        supports: ["roundtrip"],
        normalizeTarget(target) {
          return { id: target.id, metadata: target.metadata };
        },
        async probe() {
          return { details: [], healthy: true };
        },
        async send() {
          return { accepted: true, messageId: "sent-1", threadId: "thread-1" };
        },
        async waitForInbound(context) {
          waitCalls += 1;
          expect(context.timeoutMs).toBeLessThanOrEqual(30);
          if (waitCalls === 1) {
            wallNow += wallShift;
          }
          return {
            author: "assistant",
            id: "repeated",
            provider: "mock",
            sentAt: new Date(wallNow).toISOString(),
            text: "not the requested nonce",
            threadId: "thread-1",
          };
        },
      };
      const registry: Registry = {
        catalog: OPENCLAW_SUPPORT_CATALOG,
        resolve() {
          return provider;
        },
      };
      const boundedManifest: ManifestDefinition = {
        ...manifest,
        fixtures: [{ ...manifest.fixtures[0]!, retries: 0, timeoutMs: 30 }],
      };

      try {
        const result = await runFixtureCommand({
          fixtureId: "fixture",
          manifest: boundedManifest,
          manifestPath: "/tmp/crabline.yaml",
          registry,
        });

        expect(result).toMatchObject({ failureKind: "timeout", ok: false });
        expect(waitCalls).toBeGreaterThan(1);
        expect(waitCalls).toBeLessThan(10);
      } finally {
        dateNowSpy.mockRestore();
      }
    },
  );

  it("retries after a timeout and succeeds", async () => {
    let waitCalls = 0;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["probe", "send", "roundtrip", "agent"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send() {
        return { accepted: true, messageId: "sent-1", threadId: "thread-1" };
      },
      async waitForInbound(context) {
        waitCalls += 1;
        if (waitCalls === 1) {
          return null;
        }
        return {
          author: "assistant",
          id: "inbound-1",
          provider: "mock",
          sentAt: new Date().toISOString(),
          text: `ACK ${context.nonce}`,
          threadId: "thread-1",
        };
      },
    };

    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    const result = await runFixtureCommand({
      fixtureId: "fixture",
      manifest,
      manifestPath: "/tmp/crabline.yaml",
      registry,
    });

    expect(result.ok).toBe(true);
    expect(waitCalls).toBe(2);
  });

  it("drains an aborted wait before retrying or cleaning up", async () => {
    let activeWaits = 0;
    let maxActiveWaits = 0;
    let sendCalls = 0;
    let waitCalls = 0;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["probe", "send", "roundtrip", "agent"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send() {
        sendCalls += 1;
        expect(activeWaits).toBe(0);
        return { accepted: true, messageId: `sent-${sendCalls}`, threadId: "thread-1" };
      },
      async waitForInbound(context) {
        waitCalls += 1;
        activeWaits += 1;
        maxActiveWaits = Math.max(maxActiveWaits, activeWaits);
        if (waitCalls === 1) {
          return await new Promise<null>((resolve) => {
            context.signal?.addEventListener(
              "abort",
              () => {
                setTimeout(() => {
                  activeWaits -= 1;
                  resolve(null);
                }, 25);
              },
              { once: true },
            );
          });
        }
        activeWaits -= 1;
        return {
          author: "assistant",
          id: "inbound-1",
          provider: "mock",
          sentAt: new Date().toISOString(),
          text: `ACK ${context.nonce}`,
          threadId: "thread-1",
        };
      },
      async cleanup() {
        expect(activeWaits).toBe(0);
      },
    };
    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    const result = await runFixtureCommand({
      fixtureId: "fixture",
      manifest,
      manifestPath: "/tmp/crabline.yaml",
      registry,
    });

    expect(result.ok).toBe(true);
    expect(sendCalls).toBe(2);
    expect(maxActiveWaits).toBe(1);
  });

  it("stops retrying and lets cleanup cancel an aborted wait that does not settle", async () => {
    let cleanupCalls = 0;
    let keepAlive: ReturnType<typeof setInterval> | undefined;
    let releaseWait: (() => void) | undefined;
    let sendCalls = 0;
    let waitCalls = 0;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["probe", "send", "roundtrip", "agent"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send() {
        sendCalls += 1;
        return { accepted: true, messageId: "sent-1", threadId: "thread-1" };
      },
      async waitForInbound() {
        waitCalls += 1;
        return await new Promise<null>((resolve) => {
          keepAlive = setInterval(() => undefined, 1_000);
          releaseWait = () => resolve(null);
        });
      },
      async cleanup() {
        cleanupCalls += 1;
        clearInterval(keepAlive);
        releaseWait?.();
      },
    };
    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    const result = await runFixtureCommand({
      fixtureId: "fixture",
      manifest,
      manifestPath: "/tmp/crabline.yaml",
      registry,
    });

    expect(result).toMatchObject({ failureKind: "inbound", ok: false });
    expect(result.diagnostics).toContain(
      "Provider inbound wait did not settle within 250ms after abort.",
    );
    expect(sendCalls).toBe(1);
    expect(waitCalls).toBe(1);
    expect(cleanupCalls).toBe(1);
  });

  it("does not retry an outbound send that ignores cancellation", async () => {
    let cleanupCalls = 0;
    let releaseSend: (() => void) | undefined;
    let sendCalls = 0;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["probe", "send", "roundtrip", "agent"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send() {
        sendCalls += 1;
        return await new Promise((resolve) => {
          releaseSend = () =>
            resolve({ accepted: true, messageId: "sent-late", threadId: "thread-1" });
        });
      },
      async waitForInbound() {
        throw new Error("wait must not run");
      },
      async cleanup() {
        cleanupCalls += 1;
        releaseSend?.();
      },
    };
    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    const result = await runFixtureCommand({
      fixtureId: "fixture",
      manifest,
      manifestPath: "/tmp/crabline.yaml",
      registry,
    });

    expect(result).toMatchObject({ failureKind: "timeout", ok: false });
    expect(result.diagnostics).toContain("Provider send did not settle within 250ms after abort.");
    expect(sendCalls).toBe(1);
    expect(cleanupCalls).toBe(1);
  });

  it("does not retry an accepted send that settles during abort grace", async () => {
    let cleanupCalls = 0;
    let sendCalls = 0;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["send"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send(context) {
        sendCalls += 1;
        return await new Promise((resolve) => {
          context.signal?.addEventListener(
            "abort",
            () => {
              setTimeout(() => {
                resolve({
                  accepted: true,
                  messageId: "accepted-after-deadline",
                  threadId: "thread-1",
                });
              }, 25);
            },
            { once: true },
          );
        });
      },
      async waitForInbound() {
        throw new Error("wait must not run");
      },
      async cleanup() {
        cleanupCalls += 1;
      },
    };
    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    const result = await runFixtureCommand({
      fixtureId: "fixture",
      manifest,
      manifestPath: "/tmp/crabline.yaml",
      modeOverride: "send",
      registry,
    });

    expect(result).toMatchObject({ failureKind: "timeout", ok: false });
    expect(result.diagnostics).toContain("Provider send timed out after 10ms.");
    expect(sendCalls).toBe(1);
    expect(cleanupCalls).toBe(1);
  });

  it("bounds cleanup after an inbound wait ignores cancellation", async () => {
    let releaseWait: (() => void) | undefined;
    const provider: ProviderAdapter = {
      id: "mock",
      platform: "loopback",
      status: "ready",
      supports: ["probe", "send", "roundtrip", "agent"],
      normalizeTarget(target) {
        return { id: target.id, metadata: target.metadata };
      },
      async probe() {
        return { details: [], healthy: true };
      },
      async send() {
        return { accepted: true, messageId: "sent-1", threadId: "thread-1" };
      },
      async waitForInbound() {
        return await new Promise<null>((resolve) => {
          releaseWait = () => resolve(null);
        });
      },
      async cleanup() {
        await new Promise(() => undefined);
      },
    };
    const registry: Registry = {
      catalog: OPENCLAW_SUPPORT_CATALOG,
      resolve() {
        return provider;
      },
    };

    try {
      const result = await runFixtureCommand({
        fixtureId: "fixture",
        manifest,
        manifestPath: "/tmp/crabline.yaml",
        registry,
      });

      expect(result).toMatchObject({ failureKind: "inbound", ok: false });
      expect(result.diagnostics).toContain(
        "cleanup failed: Provider cleanup did not settle within 250ms after an aborted operation.",
      );
    } finally {
      releaseWait?.();
    }
  });
});

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

name: Release

on:
  push:
    tags: ["v*"]
  workflow_dispatch:
    inputs:
      tag_name:
        description: Existing release tag to publish, or current version tag for a dry run
        required: true
        type: string
      dry_run:
        description: Verify and pack the selected commit without publishing
        type: boolean
        default: false

permissions: {}

concurrency:
  group: release
  cancel-in-progress: false
  queue: max

jobs:
  verify:
    runs-on: ubuntu-latest
    timeout-minutes: 20
    permissions:
      contents: read
    outputs:
      commit: ${{ steps.release-commit.outputs.commit }}
      integrity: ${{ steps.package.outputs.integrity }}
      name: ${{ steps.package.outputs.name }}
      tag: ${{ steps.release.outputs.tag }}
      version: ${{ steps.release.outputs.version }}
    steps:
      - name: Resolve release tag
        id: release
        env:
          GITHUB_EVENT_NAME: ${{ github.event_name }}
          GITHUB_REF_NAME: ${{ github.ref_name }}
          GITHUB_REF_TYPE: ${{ github.ref_type }}
          INPUT_TAG: ${{ inputs.tag_name }}
          INPUT_DRY_RUN: ${{ inputs.dry_run }}
        run: |
          set -euo pipefail
          tag="${INPUT_TAG:-${GITHUB_REF_NAME}}"
          [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]
          if [[ "${INPUT_DRY_RUN:-false}" == "true" ]]; then
            [[ "$GITHUB_EVENT_NAME" == "workflow_dispatch" ]]
          else
            [[ "$GITHUB_REF_TYPE" == "tag" ]]
            [[ "$GITHUB_REF_NAME" == "$tag" ]]
          fi
          echo "tag=$tag" >> "$GITHUB_OUTPUT"
          echo "version=${tag#v}" >> "$GITHUB_OUTPUT"
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
          ref: ${{ github.sha }}
      - name: Verify checked out release tag
        id: release-commit
        env:
          GITHUB_EVENT_SHA: ${{ github.sha }}
          RELEASE_TAG: ${{ steps.release.outputs.tag }}
          INPUT_DRY_RUN: ${{ inputs.dry_run }}
        run: |
          set -euo pipefail
          if [[ "${INPUT_DRY_RUN:-false}" == "true" ]]; then
            release_commit="$(git rev-parse HEAD)"
          else
            release_commit="$(git rev-parse "refs/tags/${RELEASE_TAG}^{commit}")"
          fi
          [[ "$release_commit" == "$(git rev-parse HEAD)" ]]
          [[ "$release_commit" == "$GITHUB_EVENT_SHA" ]]
          echo "commit=$release_commit" >> "$GITHUB_OUTPUT"
      - name: Verify release metadata
        env:
          RELEASE_VERSION: ${{ steps.release.outputs.version }}
        run: |
          set -euo pipefail
          node --input-type=module <<'NODE'
          import fs from "node:fs";

          const version = process.env.RELEASE_VERSION;
          const packageJson = JSON.parse(fs.readFileSync("package.json", "utf8"));
          if (packageJson.version !== version) {
            throw new Error(
              `package.json version ${packageJson.version} does not match release ${version}.`,
            );
          }

          const headingPrefix = `## ${version} - `;
          const headings = fs
            .readFileSync("CHANGELOG.md", "utf8")
            .split(/\r?\n/u)
            .filter((line) => line.startsWith(headingPrefix));
          const headingDate =
            headings.length === 1 ? headings[0].slice(headingPrefix.length) : "";
          const parsedDate = new Date(`${headingDate}T00:00:00.000Z`);
          const validDate =
            /^\d{4}-\d{2}-\d{2}$/u.test(headingDate) &&
            Number.isFinite(parsedDate.getTime()) &&
            parsedDate.toISOString().slice(0, 10) === headingDate;
          if (headings.length !== 1 || !validDate) {
            throw new Error(`CHANGELOG.md must contain exactly one "${headingPrefix}YYYY-MM-DD" heading.`);
          }
          NODE
      - uses: pnpm/action-setup@ea17c68df8912ef543352723c149a84f56e3d413 # v6.1.0
        with:
          version: 11.28.5
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 22
          cache: pnpm
          registry-url: https://registry.npmjs.org
      - run: npm install -g npm@12.0.2
      - run: pnpm install --frozen-lockfile
      - run: pnpm build
      - run: pnpm verify
      - name: Pack and verify release artifact
        id: package
        env:
          RELEASE_VERSION: ${{ steps.release.outputs.version }}
        run: |
          set -euo pipefail
          metadata_path="$RUNNER_TEMP/npm-pack.json"
          npm pack --ignore-scripts --json --pack-destination "$RUNNER_TEMP" > "$metadata_path"
          node --input-type=module <<'NODE'
          import { execFileSync } from "node:child_process";
          import fs from "node:fs";
          import path from "node:path";

          const pack = extractPackMetadata(
            fs.readFileSync(`${process.env.RUNNER_TEMP}/npm-pack.json`, "utf8"),
          );
          const packageJson = JSON.parse(fs.readFileSync("package.json", "utf8"));
          const cliPath = packageJson.bin?.crabline?.replace(/^\.\//u, "");
          if (!cliPath || !pack.files?.some((file) => file.path === cliPath)) {
            throw new Error(`Packed artifact is missing the crabline CLI at ${cliPath ?? "<unset>"}.`);
          }
          if (!pack.integrity || !pack.filename) {
            throw new Error("npm pack did not report artifact integrity and filename.");
          }
          const tarballPath = path.join(process.env.RUNNER_TEMP, pack.filename);
          const extractionRoot = fs.mkdtempSync(path.join(process.env.RUNNER_TEMP, "crabline-pack-"));
          execFileSync("tar", ["-xzf", tarballPath, "-C", extractionRoot]);
          const packedCliPath = path.join(extractionRoot, "package", cliPath);
          if (!fs.readFileSync(packedCliPath, "utf8").startsWith("#!/usr/bin/env node\n")) {
            throw new Error(`Packed CLI ${cliPath} is missing its Node shebang.`);
          }
          if (pack.version !== process.env.RELEASE_VERSION) {
            throw new Error(
              `Packed version ${pack.version} does not match release ${process.env.RELEASE_VERSION}.`,
            );
          }

          const outputs = {
            integrity: pack.integrity,
            name: packageJson.name,
            tarball: tarballPath,
          };
          fs.appendFileSync(
            process.env.GITHUB_OUTPUT,
            Object.entries(outputs)
              .map(([key, value]) => `${key}=${value}\n`)
              .join(""),
          );

          function extractPackMetadata(output) {
            let pack;
            for (let start = 0; start < output.length; start += 1) {
              if (!isJsonDocumentStart(output, start)) {
                continue;
              }
              const end = findJsonDocumentEnd(output, start);
              if (end === -1) {
                continue;
              }
              try {
                const metadata = JSON.parse(output.slice(start, end));
                const packs = Array.isArray(metadata) ? metadata : Object.values(metadata);
                if (packs.length === 1 && Array.isArray(packs[0]?.files)) {
                  pack = packs[0];
                }
              } catch {
                // Lifecycle output may contain JSON-like text before the metadata document.
              }
              start = end - 1;
            }
            if (!pack) {
              throw new Error("npm pack did not return package metadata.");
            }
            return pack;
          }

          function isJsonDocumentStart(output, index) {
            if (output[index] !== "{" && output[index] !== "[") {
              return false;
            }
            const lineStart = output.lastIndexOf("\n", index - 1) + 1;
            return output.slice(lineStart, index).trim() === "";
          }

          function findJsonDocumentEnd(output, start) {
            const closingTokens = [];
            let escaped = false;
            let inString = false;
            for (let index = start; index < output.length; index += 1) {
              const token = [REDACTED]];
              if (inString) {
                if (escaped) {
                  escaped = false;
                } else if (token === "\\") {
                  escaped = true;
                } else if (token === '"') {
                  inString = false;
                }
                continue;
              }
              if (token === '"') {
                inString = true;
              } else if (token === "{") {
                closingTokens.push("}");
              } else if (token === "[") {
                closingTokens.push("]");
              } else if (token === "}" || token === "]") {
                if (closingTokens.pop() !== token) {
                  return -1;
                }
                if (closingTokens.length === 0) {
                  return index + 1;
                }
              }
            }
            return -1;
          }
          NODE
      - name: Upload verified release artifact
        uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        with:
          compression-level: 0
          if-no-files-found: error
          name: npm-package
          path: ${{ steps.package.outputs.tarball }}
          retention-days: 1

  publish:
    if: ${{ !inputs.dry_run }}
    needs: verify
    runs-on: ubuntu-latest
    timeout-minutes: 10
    permissions:
      contents: read
      id-token: write
    steps:
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version: 24
          registry-url: https://registry.npmjs.org
      - run: npm install -g npm@12.0.2
      - name: Download verified release artifact
        uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
        with:
          name: npm-package
          path: ${{ runner.temp }}/release
      - name: Publish package with npm provenance
        env:
          GITHUB_EVENT_SHA: ${{ github.sha }}
          PACKAGE_INTEGRITY: ${{ needs.verify.outputs.integrity }}
          PACKAGE_NAME: ${{ needs.verify.outputs.name }}
          RELEASE_TAG: ${{ needs.verify.outputs.tag }}
          RELEASE_VERSION: ${{ needs.verify.outputs.version }}
          VERIFIED_COMMIT: ${{ needs.verify.outputs.commit }}
        run: |
          set -euo pipefail
          shopt -s nullglob
          tarballs=("$RUNNER_TEMP"/release/*.tgz)
          if [[ "${#tarballs[@]}" -ne 1 ]]; then
            echo "::error::Expected one verified npm tarball, found ${#tarballs[@]}."
            exit 1
          fi
          PACKAGE_TARBALL="${tarballs[0]}"

          PACKAGE_TARBALL="$PACKAGE_TARBALL" node --input-type=module <<'NODE'
          import { createHash, timingSafeEqual } from "node:crypto";
          import fs from "node:fs";

          const integrity = process.env.PACKAGE_INTEGRITY;
          const match = /^sha512-([A-Za-z0-9+/]+={0,2})$/u.exec(integrity);
          if (!match) {
            throw new Error(`Expected a sha512 SRI value, got ${integrity}.`);
          }
          const expected = Buffer.from(match[1], "base64");
          const actual = createHash("sha512")
            .update(fs.readFileSync(process.env.PACKAGE_TARBALL))
            .digest();
          if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) {
            throw new Error(`Downloaded npm tarball does not match expected integrity ${integrity}.`);
          }
          NODE

          verify_package_provenance() {
            local audit_dir audit_path
            audit_dir="$(mktemp -d "$RUNNER_TEMP/crabline-provenance.XXXXXX")"
            audit_path="$audit_dir/audit.json"
            if ! (
              cd "$audit_dir"
              npm install --ignore-scripts --no-audit --no-fund "$PACKAGE_NAME@$RELEASE_VERSION" >/dev/null 2>&1
              npm audit signatures --json --include-attestations=true > "$audit_path" 2>/dev/null
            ); then
              rm -rf "$audit_dir"
              return 3
            fi
            if ! PACKAGE_AUDIT_PATH="$audit_path" node --input-type=module 2>/dev/null -e '
            import fs from "node:fs";

            const packageName = process.env.PACKAGE_NAME;
            const releaseVersion = process.env.RELEASE_VERSION;
            const releaseRef = "refs/tags/" + process.env.RELEASE_TAG;
            const repository =
              process.env.GITHUB_SERVER_URL.replace(/\/$/u, "") +
              "/" +
              process.env.GITHUB_REPOSITORY;
            const expectedSubject =
              "pkg:npm/" +
              (packageName.startsWith("@") ? "%40" + packageName.slice(1) : packageName) +
              "@" +
              releaseVersion;
            const integrityMatch = /^sha512-([A-Za-z0-9+/]+={0,2})$/u.exec(
              process.env.PACKAGE_INTEGRITY,
            );
            if (!integrityMatch) {
              process.exit(1);
            }
            const expectedDigest = Buffer.from(integrityMatch[1], "base64").toString("hex");
            const audit = JSON.parse(fs.readFileSync(process.env.PACKAGE_AUDIT_PATH, "utf8"));
            const verified = Array.isArray(audit.verified)
              ? audit.verified.find(
                  (entry) => entry?.name === packageName && entry?.version === releaseVersion,
                )
              : undefined;
            const bundles = Array.isArray(verified?.attestationBundles)
              ? verified.attestationBundles
              : [];
            const valid = bundles.some((attestation) => {
              if (attestation?.predicateType !== "https://slsa.dev/provenance/v1") {
                return false;
              }
              try {
                const statement = JSON.parse(
                  Buffer.from(attestation.bundle.dsseEnvelope.payload, "base64").toString("utf8"),
                );
                const workflow =
                  statement.predicate?.buildDefinition?.externalParameters?.workflow;
                const dependencies =
                  statement.predicate?.buildDefinition?.resolvedDependencies;
                return (
                  statement._type === "https://in-toto.io/Statement/v1" &&
                  statement.predicateType === "https://slsa.dev/provenance/v1" &&
                  statement.predicate?.buildDefinition?.buildType ===
                    "https://slsa-framework.github.io/github-actions-buildtypes/workflow/v1" &&
                  Array.isArray(statement.subject) &&
                  statement.subject.some(
                    (subject) =>
                      subject?.name === expectedSubject &&
                      subject?.digest?.sha512 === expectedDigest,
                  ) &&
                  workflow?.repository === repository &&
                  workflow?.path === ".github/workflows/release.yml" &&
                  workflow?.ref === releaseRef &&
                  Array.isArray(dependencies) &&
                  dependencies.some(
                    (dependency) =>
                      dependency?.uri === "git+" + repository + "@" + releaseRef &&
                      dependency?.digest?.gitCommit === process.env.VERIFIED_COMMIT,
                  )
                );
              } catch {
                return false;
              }
            });
            process.exit(valid ? 0 : 1);
            '; then
              rm -rf "$audit_dir"
              echo "::error::Published $PACKAGE_NAME@$RELEASE_VERSION has provenance that does not match the repository, workflow, tag, commit, or package integrity."
              return 2
            fi
            rm -rf "$audit_dir"
            return 0
          }

          check_existing_package() {
            local actual_integrity actual_version provenance_status
            if ! actual_integrity="$(npm view "$PACKAGE_NAME@$RELEASE_VERSION" dist.integrity 2>/dev/null)"; then
              return 1
            fi
            if ! actual_version="$(npm view "$PACKAGE_NAME@$RELEASE_VERSION" version 2>/dev/null)"; then
              return 1
            fi
            if [[ "$actual_version" != "$RELEASE_VERSION" ]]; then
              echo "::error::Published $PACKAGE_NAME@$RELEASE_VERSION reports version $actual_version."
              return 2
            fi
            if [[ "$actual_integrity" != "$PACKAGE_INTEGRITY" ]]; then
              echo "::error::Published $PACKAGE_NAME@$RELEASE_VERSION has integrity $actual_integrity, expected $PACKAGE_INTEGRITY."
              return 2
            fi
            if verify_package_provenance; then
              return 0
            else
              provenance_status=$?
              return "$provenance_status"
            fi
          }

          verify_published_package() {
            local delay existing_status
            # npm processing can delay metadata and attestations for several minutes.
            for delay in 2 4 8 16 30 60 60 60 60 60; do
              sleep "$delay"
              if check_existing_package; then
                return 0
              else
                existing_status=$?
                if [[ "$existing_status" -eq 2 ]]; then
                  return 2
                fi
              fi
            done
            return 1
          }

          revalidate_release_tag() {
            local remote_commit remote_refs
            if [[ "$GITHUB_EVENT_SHA" != "$VERIFIED_COMMIT" ]]; then
              echo "::error::Release run commit $GITHUB_EVENT_SHA does not match verified commit $VERIFIED_COMMIT."
              return 1
            fi
            remote_refs="$(
              git ls-remote --exit-code \
                "$GITHUB_SERVER_URL/$GITHUB_REPOSITORY.git" \
                "refs/tags/$RELEASE_TAG" \
                "refs/tags/$RELEASE_TAG^{}"
            )"
            remote_commit="$(
              awk -v direct="refs/tags/$RELEASE_TAG" -v peeled="refs/tags/$RELEASE_TAG^{}" '
                $2 == peeled { peeled_sha = $1 }
                $2 == direct { direct_sha = $1 }
                END { print (peeled_sha != "" ? peeled_sha : direct_sha) }
              ' <<< "$remote_refs"
            )"
            if [[ -z "$remote_commit" || "$remote_commit" != "$VERIFIED_COMMIT" ]]; then
              echo "::error::Release tag $RELEASE_TAG resolves to ${remote_commit:-<missing>}, expected $VERIFIED_COMMIT."
              return 1
            fi
          }

          guard_latest_version() {
            local latest_version
            if ! latest_version="$(npm view "$PACKAGE_NAME@latest" version 2>/dev/null)"; then
              echo "::error::Unable to resolve the current npm latest version for $PACKAGE_NAME."
              return 1
            fi
            node --input-type=module -e '
              const [release, latest] = process.argv.slice(1);
              const parse = (value) => {
                const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(value);
                if (!match) {
                  throw new Error("Expected a stable semantic version, got " + value + ".");
                }
                return match.slice(1).map(BigInt);
              };
              const releaseParts = parse(release);
              const latestParts = parse(latest);
              for (let index = 0; index < releaseParts.length; index += 1) {
                if (releaseParts[index] > latestParts[index]) process.exit(0);
                if (releaseParts[index] < latestParts[index]) {
                  throw new Error(
                    "Refusing to publish " +
                      release +
                      " because npm latest is newer at " +
                      latest +
                      ".",
                  );
                }
              }
            ' "$RELEASE_VERSION" "$latest_version"
          }

          publish_status=0
          if check_existing_package; then
            publication_message="$PACKAGE_NAME@$RELEASE_VERSION is already published with the expected postconditions."
          else
            existing_status=$?
            if [[ "$existing_status" -eq 2 ]]; then
              exit 1
            fi
            if [[ "$existing_status" -eq 3 ]]; then
              if verify_published_package; then
                revalidate_release_tag
                echo "$PACKAGE_NAME@$RELEASE_VERSION is already published with the expected postconditions."
                exit 0
              else
                verification_status=$?
                if [[ "$verification_status" -eq 2 ]]; then
                  exit 1
                fi
              fi
              echo "::error::Unable to verify existing $PACKAGE_NAME@$RELEASE_VERSION after bounded retries."
              exit 1
            fi

            guard_latest_version
            revalidate_release_tag
            if npm publish "$PACKAGE_TARBALL" --access public --provenance; then
              publication_message="$PACKAGE_NAME@$RELEASE_VERSION was published with npm provenance."
            else
              publish_status=$?
              publication_message="$PACKAGE_NAME@$RELEASE_VERSION was published despite the prior client error."
            fi
          fi

          if verify_published_package; then
            revalidate_release_tag
            echo "$publication_message"
            exit 0
          else
            verification_status=$?
            if [[ "$verification_status" -eq 2 ]]; then
              exit 1
            fi
          fi
          if [[ "$publish_status" -ne 0 ]]; then
            exit "$publish_status"
          fi
          echo "::error::Unable to verify published $PACKAGE_NAME@$RELEASE_VERSION after bounded retries."
          exit 1

  github-release:
    if: ${{ !inputs.dry_run }}
    needs: [verify, publish]
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      contents: write
    steps:
      - name: Create GitHub release
        env:
          GH_TOKEN: ${{ github.token }}
          GITHUB_EVENT_SHA: ${{ github.sha }}
          RELEASE_TAG: ${{ needs.verify.outputs.tag }}
          VERIFIED_COMMIT: ${{ needs.verify.outputs.commit }}
        run: |
          set -euo pipefail
          revalidate_release_tag() {
            local remote_commit remote_refs
            if [[ "$GITHUB_EVENT_SHA" != "$VERIFIED_COMMIT" ]]; then
              echo "::error::Release run commit $GITHUB_EVENT_SHA does not match verified commit $VERIFIED_COMMIT."
              return 1
            fi
            remote_refs="$(
              git ls-remote --exit-code \
                "$GITHUB_SERVER_URL/$GITHUB_REPOSITORY.git" \
                "refs/tags/$RELEASE_TAG" \
                "refs/tags/$RELEASE_TAG^{}"
            )"
            remote_commit="$(
              awk -v direct="refs/tags/$RELEASE_TAG" -v peeled="refs/tags/$RELEASE_TAG^{}" '
                $2 == peeled { peeled_sha = $1 }
                $2 == direct { direct_sha = $1 }
                END { print (peeled_sha != "" ? peeled_sha : direct_sha) }
              ' <<< "$remote_refs"
            )"
            if [[ -z "$remote_commit" || "$remote_commit" != "$VERIFIED_COMMIT" ]]; then
              echo "::error::Release tag $RELEASE_TAG resolves to ${remote_commit:-<missing>}, expected $VERIFIED_COMMIT."
              return 1
            fi
          }

          release_error="$RUNNER_TEMP/gh-release-view-error"
          if release_state="$(gh release view "$RELEASE_TAG" \
            --repo "$GITHUB_REPOSITORY" \
            --json isDraft,isPrerelease \
            --jq '[.isDraft, .isPrerelease] | @tsv' 2>"$release_error")"; then
            rm -f "$release_error"
            if [[ "$release_state" != $'false\tfalse' ]]; then
              echo "::error::GitHub release $RELEASE_TAG exists but is draft or prerelease."
              exit 1
            fi
            revalidate_release_tag
            echo "GitHub release $RELEASE_TAG already exists."
            exit 0
          else
            view_status=$?
          fi
          view_error="$(cat "$release_error")"
          rm -f "$release_error"
          if [[ "$view_status" -ne 1 || "$view_error" != *"release not found"* ]]; then
            echo "::error::Unable to inspect GitHub release $RELEASE_TAG."
            printf '%s\n' "$view_error" >&2
            exit "$view_status"
          fi
          revalidate_release_tag
          gh release create "$RELEASE_TAG" \
            --repo "$GITHUB_REPOSITORY" \
            --generate-notes \
            --verify-tag

import { CrablineError } from "../../core/errors.js";
import { isLoopbackHost } from "../../servers/http.js";

type WebhookConfig = {
  host?: string | undefined;
  publicUrl?: string | undefined;
};

export function requireExternalWebhookAuthentication(params: {
  authenticated: boolean;
  authenticatedIngressUrls?: readonly string[] | undefined;
  provider: string;
  requirement: string;
  webhook: WebhookConfig | undefined;
}): void {
  const host = params.webhook?.host ?? "127.0.0.1";
  const hostIsLoopback = isLoopbackHost(host);
  const publicUrls = [
    ...(params.authenticatedIngressUrls ?? []),
    ...(params.webhook?.publicUrl ? [params.webhook.publicUrl] : []),
  ];
  const callbackUrls = publicUrls.map((publicUrl) => {
    try {
      const url = new URL(publicUrl);
      return {
        isLoopback: hostIsLoopback && isLoopbackHost(url.hostname),
        url,
      };
    } catch (error) {
      throw new CrablineError(`${params.provider} public callback URL is invalid.`, {
        cause: error,
        kind: "config",
      });
    }
  });
  for (const callbackUrl of callbackUrls) {
    if (callbackUrl.url.protocol !== "http:" && callbackUrl.url.protocol !== "https:") {
      throw new CrablineError(
        `${params.provider} authenticated external webhooks require HTTPS; plain HTTP is allowed only for loopback-local ingress.`,
        { kind: "config" },
      );
    }
  }
  const externallyReachable =
    !hostIsLoopback || callbackUrls.some((callbackUrl) => !callbackUrl.isLoopback);
  if (externallyReachable && !params.authenticated) {
    throw new CrablineError(
      `${params.provider} externally reachable webhooks require ${params.requirement}.`,
      { kind: "config" },
    );
  }
  if (!externallyReachable) {
    return;
  }
  if (publicUrls.length === 0) {
    throw new CrablineError(
      `${params.provider} authenticated external webhooks require a public callback URL with HTTPS.`,
      { kind: "config" },
    );
  }

  for (const callbackUrl of callbackUrls) {
    const safeLoopbackHttp = callbackUrl.url.protocol === "http:" && callbackUrl.isLoopback;
    if (callbackUrl.url.protocol !== "https:" && !safeLoopbackHttp) {
      throw new CrablineError(
        `${params.provider} authenticated external webhooks require HTTPS; plain HTTP is allowed only for loopback-local ingress.`,
        { kind: "config" },
      );
    }
  }
}

