import { afterEach, describe, expect, it } from "vitest";
import {
  CRABLINE_SERVER_CHANNELS,
  startCrablineServer,
  type StartedCrablineServer,
  type StartCrablineServerParams,
} from "../src/servers/index.js";

const servers: StartedCrablineServer[] = [];

afterEach(async () => {
  await Promise.all(servers.splice(0).map((server) => server.close()));
});

describe("provider server dispatcher", () => {
  it("routes every declared server channel", async () => {
    for (const channel of CRABLINE_SERVER_CHANNELS) {
      const server = await startCrablineServer({ channel } as StartCrablineServerParams);
      servers.push(server);
      expect(server.manifest.provider).toBe(channel);
    }
  });

  it("rejects unknown channels", async () => {
    await expect(
      startCrablineServer({ channel: "unknown" } as unknown as StartCrablineServerParams),
    ).rejects.toThrow("Unsupported server channel");
  });
});

import path from "node:path";
import { createClient } from "matrix-js-sdk";
import { describe, expect, it } from "vitest";
import { startMatrixServer } from "../src/index.js";
import { createTempDir, disposeTempDir } from "./test-helpers.js";

describe("Matrix state queries", () => {
  it("returns the same state through sync and native SDK event queries", async () => {
    const directory = await createTempDir();
    const roomId = "!state:matrix.test";
    const server = await startMatrixServer({
      recorderPath: path.join(directory, "matrix.jsonl"),
      roomId,
    });
    try {
      const { manifest } = server;
      const client = createClient({
        accessToken: [REDACTED],
        baseUrl: manifest.baseUrl,
        userId: manifest.botUserId,
      });
      const response = await fetch(manifest.endpoints.syncUrl + "?timeout=0", {
        headers: { authorization: "Bearer " + manifest.accessToken },
      });
      const sync = (await response.json()) as {
        rooms: {
          join: Record<
            string,
            { state: { events: { content: unknown; state_key: string; type: string }[] } }
          >;
        };
      };
      const events = sync.rooms.join[roomId]!.state.events;
      expect(events.map((event) => event.type)).toContain("m.room.create");
      for (const event of events) {
        await expect(client.getStateEvent(roomId, event.type, event.state_key)).resolves.toEqual(
          event.content,
        );
      }
      await expect(client.getStateEvent(roomId, "m.room.unknown", "")).rejects.toMatchObject({
        errcode: "M_NOT_FOUND",
        httpStatus: 404,
      });
      await expect(
        client.getStateEvent(roomId, "m.room.member", "@missing:matrix.test"),
      ).rejects.toMatchObject({
        errcode: "M_NOT_FOUND",
        error: "Unknown room member",
        httpStatus: 404,
      });
    } finally {
      await server.close();
      await disposeTempDir(directory);
    }
  });
});

import { mkdtemp, readdir, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, it, vi } from "vitest";

const native = vi.hoisted(() => ({ commands: [] as string[] }));
vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return {
    ...actual,
    spawnSync(command: string) {
      native.commands.push(command);
      const stdout =
        command === "/usr/sbin/sysctl"
          ? "{ sec = 1000, usec = 0 }"
          : command === "/usr/bin/vmmap"
            ? "Launch Time: 2026-08-28 00:00:00.000000 +0000"
            : command === "/usr/sbin/ioreg"
              ? '"IOPlatformUUID" = "test-machine"'
              : "";
      return { status: 0, stdout, stderr: "" };
    },
  };
});

beforeEach(() => {
  vi.resetModules();
  vi.spyOn(process, "platform", "get").mockReturnValue("darwin");
  native.commands.length = 0;
});
afterEach(() => vi.restoreAllMocks());

it.each([
  "startDiscordServer",
  "startMattermostServer",
  "startMatrixServer",
  "startSignalServer",
  "startSlackServer",
  "startTelegramServer",
  "startWhatsAppServer",
  "startZaloServer",
] as const)(
  "%s initializes recorder ownership before readiness without artifacts",
  async (name) => {
    const api = await import("../src/index.js");
    const directory = await mkdtemp(path.join(os.tmpdir(), "crabline-cold-recorder-"));
    const observer = vi.fn();
    const server = await api[name]({
      onEvent: observer,
      recorderPath: path.join(directory, "missing", "events.jsonl"),
    });
    try {
      expect(native.commands).toContain("/usr/bin/vmmap");
      expect(native.commands).toContain("/usr/sbin/ioreg");
      expect(await readdir(directory)).toEqual([]);
      expect(observer).not.toHaveBeenCalled();
    } finally {
      await server.close();
      await rm(directory, { recursive: true, force: true });
    }
  },
);
